(()=>{window.__qaProjects=null;(async()=>{try{
const all=await new Promise((resolve,reject)=>{
  const req=indexedDB.open('xray-chat-history-v1',1);
  req.onupgradeneeded=()=>req.result.createObjectStore('projects',{keyPath:'projectId'});
  req.onsuccess=()=>{const db=req.result;
    const q=db.transaction('projects').objectStore('projects').getAll();
    q.onsuccess=()=>{db.close();resolve(q.result||[])};
    q.onerror=()=>{db.close();reject(q.error)}};
  req.onerror=()=>reject(req.error)});
window.__qaProjects={projects:all.map(p=>({projectId:p.projectId,revision:p.revision,activeId:p.activeId??null,
 threads:(p.threads||[]).length,
 assistantEntries:(p.threads||[]).reduce((n,t)=>n+(t.entries||[]).filter(e=>e.kind==='assistant').length,0),
 userEntries:(p.threads||[]).reduce((n,t)=>n+(t.entries||[]).filter(e=>e.kind==='user').length,0),
 toolEntries:(p.threads||[]).reduce((n,t)=>n+(t.entries||[]).filter(e=>e.kind==='tool').length,0),
 lastUserText:((p.threads||[]).flatMap(t=>(t.entries||[]).filter(e=>e.kind==='user')).at(-1)?.text||'').slice(0,120)}))};
}catch(e){window.__qaProjects={error:String(e)}}})();return 'enumerating'})()

(()=>{window.__qaScan=null;(async()=>{try{
const all=await new Promise((resolve,reject)=>{
  const req=indexedDB.open('xray-chat-history-v1',1);
  req.onsuccess=()=>{const db=req.result;const q=db.transaction('projects').objectStore('projects').getAll();
    q.onsuccess=()=>{db.close();resolve(q.result||[])};q.onerror=()=>{db.close();reject(q.error)}};
  req.onerror=()=>reject(req.error)});
const needles=['The user is asking','The user wants me to','The user has asked','The prior checkpoint','I should now','Let me think'];
const hits=[];
for(const p of all) for(const t of (p.threads||[])) for(const e of (t.entries||[])){
 if(e.kind!=='assistant')continue;
 const found=needles.filter(n=>(e.text||'').includes(n));
 if(found.length)hits.push({projectId:p.projectId,threadId:t.id,chars:(e.text||'').length,needles:found,head:(e.text||'').slice(0,300)});
}
window.__qaScan={projects:all.length,assistantEntriesScanned:all.reduce((n,p)=>n+(p.threads||[]).reduce((m,t)=>m+(t.entries||[]).filter(e=>e.kind==='assistant').length,0),0),
hits:hits.length,sample:hits.slice(0,6)};
}catch(e){window.__qaScan={error:String(e)}}})();return 'scanning'})()
